import assert from 'node:assert/strict';
import test from 'node:test';
import { computeMapGeometry } from './geo/build-layout';
import { DISTRICT_IDS, getMapGeometry, resolveDarkness } from './geography';

// The map the app serves is a file, generated by `npm run build:map`. This is
// the guard that it still matches the GeoJSON and the style constants it was
// generated from: edit either and this fails until the layout is rebuilt.
test('map-layout.json is in step with the data it came from', () => {
  assert.deepEqual(getMapGeometry(), computeMapGeometry());
});

test('every district is present, with a label on the frame', () => {
  const { districts, width, height } = getMapGeometry();
  assert.deepEqual(
    districts.map((d) => d.id).sort(),
    [...DISTRICT_IDS].sort(),
  );
  for (const d of districts) {
    assert.ok(d.path.startsWith('M'), `${d.id} has no path`);
    assert.ok(d.labelX > 0 && d.labelX < 1, `${d.id} label off the frame horizontally`);
    assert.ok(d.labelY > 0 && d.labelY < 1, `${d.id} label off the frame vertically`);
    assert.ok(d.label === d.label.toLocaleUpperCase('tr'), `${d.id} label is not Turkish uppercase`);
  }
  assert.equal(getMapGeometry().viewBox, `0 0 ${width} ${height}`);
});

test('settlements are projected inside the frame, west to east', () => {
  const { settlements, width, height } = getMapGeometry();
  assert.equal(settlements.length, 26);
  let previous = -Infinity;
  for (const s of settlements) {
    assert.ok(s.x >= 0 && s.x <= width, `${s.name} is outside the frame`);
    assert.ok(s.y >= 0 && s.y <= height, `${s.name} is outside the frame`);
    assert.ok(s.x >= previous, `${s.name} breaks the west-to-east order`);
    previous = s.x;
  }
});

test('a named area darkens only itself; the rest of the district stays lit', () => {
  const dark = resolveDarkness([{ district: 'lefkosa', areas: ['Gönyeli', 'Hamitköy'] }]);
  assert.ok(dark.districts.has('lefkosa'));
  assert.deepEqual([...dark.settlements].sort(), ['Gönyeli', 'Hamitköy']);
  assert.ok(!dark.settlements.has('Lefkoşa'));
});

test('an area named with different diacritics still matches its settlement', () => {
  const dark = resolveDarkness([{ district: 'gazimagusa', areas: ['YENIBOGAZICI'] }]);
  assert.deepEqual([...dark.settlements], ['Yeniboğaziçi']);
});

test('an outage naming nothing we know darkens the whole district', () => {
  const dark = resolveDarkness([{ district: 'lefke', areas: ['Bilinmeyen Mahalle'] }]);
  const lefke = getMapGeometry()
    .settlements.filter((s) => s.district === 'lefke')
    .map((s) => s.name);
  assert.deepEqual([...dark.settlements].sort(), lefke.sort());
});
